+        Operation operation = irBooleanNode.getOperation();
+        ExpressionNode irLeftNode = irBooleanNode.getLeftNode();
+        ExpressionNode irRightNode = irBooleanNode.getRightNode();
+
+        if (operation == Operation.AND) {
+            Label fals = new Label();
+            Label end = new Label();
