+            .setTrackTotalHitsUpTo(Integer.MAX_VALUE).setSize(0).get();
+        ElasticsearchAssertions.assertNoFailures(searchResponse);
+        assertThat(searchResponse.getHits().getTotalHits().value, equalTo((long) maxDocs.get()));
+        if (randomBoolean()) {
